orte.php?'.http_build_query(['network'=>$networkId,'agent'=>$selectedAgentId,'q'=>$search,'status'=>$filter,'p'=>$page+1]))?>" aria-label="Próxima" title="Próxima"><i class="fa fa-angle-right" aria-hidden="true"></i><span class="arc-action-label">Próxima</span></a><?php endif;?></nav></section>
